package com.dustline.game

import android.content.Context
import java.nio.ByteBuffer
import java.nio.ByteOrder

/**
 * The aircraft (assets/models/plane/plane.bin) - the developer's own passenger jet, generated by tools/make_plane.py.
 * 3 parts: fuselage + wings + tail + engine shells (vertex colours, no texture) and 2 spinning engine fans (own pivot).
 * Nose = -Z, up = +Y, wings along X. Draw with uMode = 1 (vertex colour).
 */
class PlaneModel(ctx: Context) {
    class Part(val prop: Boolean, val px: Float, val py: Float, val pz: Float, val verts: FloatArray, val indices: IntArray)

    val parts: List<Part>

    init {
        val b = ctx.assets.open("models/plane/plane.bin").use { it.readBytes() }
        val bb = ByteBuffer.wrap(b).order(ByteOrder.LITTLE_ENDIAN)
        var o = 0
        val n = bb.getInt(o); o += 4
        val list = ArrayList<Part>()
        for (k in 0 until n) {
            val prop = bb.getInt(o) == 1
            val px = bb.getFloat(o + 4); val py = bb.getFloat(o + 8); val pz = bb.getFloat(o + 12)
            val nv = bb.getInt(o + 16); val ni = bb.getInt(o + 20); o += 24
            val pOff = o; o += nv * 12
            val nOff = o; o += nv * 12
            val cOff = o; o += nv * 12
            val iOff = o; o += ni * 4
            val verts = FloatArray(nv * MapData.STRIDE)
            for (v in 0 until nv) {
                val d = v * MapData.STRIDE
                verts[d] = bb.getFloat(pOff + v * 12); verts[d + 1] = bb.getFloat(pOff + v * 12 + 4); verts[d + 2] = bb.getFloat(pOff + v * 12 + 8)
                verts[d + 3] = bb.getFloat(nOff + v * 12); verts[d + 4] = bb.getFloat(nOff + v * 12 + 4); verts[d + 5] = bb.getFloat(nOff + v * 12 + 8)
                verts[d + 6] = 0f; verts[d + 7] = 0f
                verts[d + 8] = bb.getFloat(cOff + v * 12); verts[d + 9] = bb.getFloat(cOff + v * 12 + 4); verts[d + 10] = bb.getFloat(cOff + v * 12 + 8)
            }
            val idx = IntArray(ni) { bb.getInt(iOff + it * 4) }
            list.add(Part(prop, px, py, pz, verts, idx))
        }
        parts = list
    }
}
